#include "cfd/core/mixed_precision.hpp"
#include <algorithm>
#include <cmath>
#include <stdexcept>
namespace cfd::core {
RefinementResult mixed_precision_iterative_refinement(const CsrMatrix&A,std::span<const double>b,std::span<double>x,std::size_t outer,std::size_t inner,double tol){if(A.rows()!=A.cols()||b.size()!=A.rows()||x.size()!=A.cols()||outer==0||inner==0||!(tol>0))throw std::invalid_argument("invalid iterative-refinement inputs");const auto diag=A.diagonal();std::vector<double>ax(b.size()),r(b.size());std::vector<float>d(diag.size()),rf(r.size()),delta(r.size()),next(r.size());for(std::size_t i=0;i<diag.size();++i){if(diag[i]==0)throw std::runtime_error("zero diagonal in iterative refinement");d[i]=static_cast<float>(diag[i]);}double bnorm=0;for(double v:b)bnorm+=v*v;bnorm=std::sqrt(bnorm);if(bnorm==0)bnorm=1;for(std::size_t out=0;out<outer;++out){A.multiply(x,ax);double rn=0;for(std::size_t i=0;i<r.size();++i){r[i]=b[i]-ax[i];rf[i]=static_cast<float>(r[i]);rn+=r[i]*r[i];delta[i]=0;}rn=std::sqrt(rn)/bnorm;if(rn<=tol)return {true,out,rn};for(std::size_t it=0;it<inner;++it){for(std::size_t row=0;row<A.rows();++row){float sum=rf[row];for(std::size_t k=A.row_offsets()[row];k<A.row_offsets()[row+1];++k){const auto col=A.column_indices()[k];if(col!=row)sum-=static_cast<float>(A.values()[k])*delta[col];}next[row]=sum/d[row];}delta.swap(next);}for(std::size_t i=0;i<x.size();++i)x[i]+=static_cast<double>(delta[i]);}A.multiply(x,ax);double rn=0;for(std::size_t i=0;i<b.size();++i){double q=b[i]-ax[i];rn+=q*q;}return {std::sqrt(rn)/bnorm<=tol,outer,std::sqrt(rn)/bnorm};}
} // namespace cfd::core
